#!/usr/bin/env python3
"""Strict validation for the required LMDB guest campaigns and selected Java tests."""
# Some portions generated by Codex
from __future__ import annotations

import argparse
import json
import re
import sys
import xml.etree.ElementTree as ET
from pathlib import Path
from typing import Any, Iterable, Sequence

from run_powercut_campaign import SCENARIOS, validate_cutpoint_witness, validate_recovery_pair


POWER_CUT_SCENARIOS = (
    "mixed-replay-before-native-commit",
    "dictionary-before-triple-commit",
    "commit-returned-before-ack",
)
SUREFIRE_TEST_CLASSES = (
    "LmdbCrashRecoveryTest",
    "LmdbStoreFlushReproductionTest",
    "TripleStoreAutoGrowTest",
    "ValueStoreTermIndexRecoveryTest",
    "LmdbConstructorCleanupTest",
    "PersistentSetFactoryTransactionOwnershipTest",
    "LmdbSnapshotValueLifetimeTest",
    "LmdbValueRetirementRecoveryTest",
    "TxnMutationJournalTest",
)
FAILSAFE_IT_CLASSES = ("LmdbStoreModelLifecycleIT",)
_SHA256 = re.compile(r"^[0-9a-f]{64}$")
_REQUIRED_PRESERVED_WITNESSES = (
    "actual-A-ack-witness.tsv",
    "actual-B-attempt-witness.tsv",
    "actual-cutpoint-witness.json",
)


def _require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def _positive_event_count(report: dict[str, Any], *names: str, label: str) -> None:
    counts = [report.get(name) for name in names]
    _require(all(type(value) is int and value >= 0 for value in counts),
             f"{label} is missing valid sync-event counts {names}")
    _require(sum(counts) > 0, f"{label} observed no successful FLUSH or FUA")


def _require_sha256(value: Any, label: str) -> str:
    _require(isinstance(value, str) and _SHA256.fullmatch(value) is not None,
             f"{label} is not a complete SHA-256 digest")
    return value


def _require_device_cut(cut: Any, label: str) -> None:
    _require(isinstance(cut, dict), f"{label} has no device-cut report")
    _require(cut.get("off") is True and cut.get("survival") == "drop" and
             type(cut.get("kept_sectors")) is int and cut["kept_sectors"] == 0,
             f"{label} did not report a completed volatile-sector drop cut")


def validate_calibration_report(report: dict[str, Any]) -> None:
    _require(report.get("result") == "PASS", "FLUSH/FUA calibration did not pass")
    _positive_event_count(report, "baseline_flush_done_count", "baseline_fua_done_count",
                          label="calibration baseline")
    raw_write = report.get("raw_overwrite_ack_before_cut")
    _require(isinstance(raw_write, dict) and raw_write.get("event") == "WRITE" and
             isinstance(raw_write.get("length"), int) and raw_write["length"] > 0 and
             raw_write.get("fua") is False,
             "calibration lacks its acknowledged unsynced raw overwrite")
    _require(report.get("durability_events_after_raw_overwrite_ack") == [],
             "calibration raw overwrite was followed by FLUSH or FUA before the cut")
    _require_device_cut(report.get("device_cut"), "calibration")
    _require_sha256(report.get("pre_recovery_image", {}).get("sha256")
                    if isinstance(report.get("pre_recovery_image"), dict) else None,
                    "calibration pre-recovery image")
    oracle = report.get("recovered_file_oracle")
    _require(isinstance(oracle, str) and oracle.startswith("PASS "),
             "calibration did not recover the synced probe and discard the volatile overwrite")
    _require(report.get("read_only_inputs_unchanged") is True,
             "calibration inputs changed during the guest campaign")


def validate_namespace_report(report: dict[str, Any]) -> None:
    _require(report.get("result") == "PUBLIC_ORACLE_PASS", "acknowledged namespace campaign did not pass")
    _require(report.get("recovery_oracle_findings") == [], "namespace recovery oracle reported findings")
    _require(report.get("public_index_context_sparql_checks_completed") is True,
             "namespace recovery omitted public index/context/SPARQL checks")
    _require(report.get("post_ack_action_order") == ["read_backend_status", "nbd_cut", "sigkill_guest"],
             "namespace campaign ran a guest sync or shutdown before the NBD cut")
    _require(report.get("writer_guest_alive_when_nbd_cut_started") is True and
             report.get("writer_guest_reaped_after_nbd_cut") is True,
             "namespace campaign did not cut the NBD device while its writer guest was live")
    _positive_event_count(report, "writer_backend_flush_done_count", "writer_backend_fua_done_count",
                          label="namespace campaign")
    namespace_commit = report.get("namespace_only_commit")
    _require(isinstance(namespace_commit, str) and "commit returned" in namespace_commit and
             "witness was fsynced" in namespace_commit and "no guest filesystem sync" in namespace_commit,
             "namespace campaign did not witness a returned commit before unsynchronized power cut")
    _require_device_cut(report.get("data_device_cut"), "namespace campaign")
    for name in ("external_witness", "namespace_witness"):
        witness = report.get(name)
        _require(isinstance(witness, dict), f"namespace campaign has no {name}")
        _require_sha256(witness.get("sha256"), f"namespace campaign {name}")
    image = report.get("pre_recovery_image")
    _require(isinstance(image, dict), "namespace campaign has no preserved pre-recovery image")
    image_hash = _require_sha256(image.get("sha256"), "namespace pre-recovery image")
    _require(report.get("pre_recovery_image_sha256_after_run") == image_hash,
             "namespace campaign changed its immutable pre-recovery image")
    _require(report.get("read_only_source_inputs_unchanged") is True and
             report.get("compiled_artifacts_unchanged") is True and
             report.get("classpath_artifacts_unchanged") is True and
             report.get("os_base_image_unchanged") is True and
             report.get("backend_source_unchanged") is True,
             "namespace campaign changed a source, build, classpath, or guest-image input")


def validate_powercut_report(report: dict[str, Any], expected_scenario: str) -> dict[str, str]:
    _require(report.get("result") == "POWER_CUT_RECOVERY_STABLE",
             f"{expected_scenario} did not complete both recovery runs")
    _require(report.get("scenario") == expected_scenario,
             f"power-cut report scenario {report.get('scenario')!r} does not match {expected_scenario!r}")
    contract = report.get("scenario_contract")
    expected_contract = json.loads(json.dumps(SCENARIOS[expected_scenario]))
    _require(contract == expected_contract, f"{expected_scenario} reports the wrong scenario contract")
    witness = report.get("cutpoint_witness")
    _require(isinstance(witness, dict), f"{expected_scenario} has no cutpoint witness")
    validate_cutpoint_witness(expected_scenario, witness, b_acknowledged=report.get("B_acknowledged") is True)
    _require(report.get("B_acknowledged") is False, f"{expected_scenario} must leave B unacknowledged")
    _require_device_cut(report.get("cut_report"), expected_scenario)
    image = report.get("pre_recovery_image")
    _require(isinstance(image, dict), f"{expected_scenario} has no preserved crash image")
    image_hash = _require_sha256(image.get("sha256"), f"{expected_scenario} crash image")
    _require(report.get("pre_recovery_image_sha256_after_both_recoveries") == image_hash,
             f"{expected_scenario} changed its crash image during recovery")
    _positive_event_count(report, "writer_nbd_flush_done_count", "writer_nbd_fua_done_count",
                          label=f"{expected_scenario} writer")
    _require(isinstance(report.get("writer_backend_status_before_cut"), dict) and
             report["writer_backend_status_before_cut"].get("ignore_flush") is False,
             f"{expected_scenario} used a backend that ignored flushes")
    external = report.get("external_witnesses")
    _require(isinstance(external, dict), f"{expected_scenario} has no preserved external witnesses")
    for name in _REQUIRED_PRESERVED_WITNESSES:
        record = external.get(name)
        _require(isinstance(record, dict), f"{expected_scenario} is missing preserved witness {name}")
        _require_sha256(record.get("sha256"), f"{expected_scenario} witness {name}")

    recoveries: list[dict[str, Any]] = []
    for label in ("recovery_1", "recovery_2"):
        details = report.get(label)
        _require(isinstance(details, dict) and isinstance(details.get("oracle"), dict),
                 f"{expected_scenario} is missing {label} public-oracle evidence")
        oracle = details["oracle"]
        _require(oracle.get("publicIndexChecks") == "COMPLETED",
                 f"{expected_scenario} {label} omitted public index/context checks")
        _require_sha256(oracle.get("stateSha256"), f"{expected_scenario} {label} full state")
        _require(oracle.get("recoveryId") not in (None, ""),
                 f"{expected_scenario} {label} has no independent recovery ID")
        recoveries.append(oracle)
    _require(str(recoveries[0]["recoveryId"]) != str(recoveries[1]["recoveryId"]),
             f"{expected_scenario} did not run two distinct recoveries")
    first = {"outcome": recoveries[0].get("outcome"), "stateSha256": recoveries[0]["stateSha256"]}
    second = {"outcome": recoveries[1].get("outcome"), "stateSha256": recoveries[1]["stateSha256"]}
    validate_recovery_pair(expected_scenario, first, second)
    _require(report.get("same_outcome_on_both_recoveries") is True and
             report.get("same_full_state_hash_on_both_recoveries") is True,
             f"{expected_scenario} did not attest stable repeated recovery")
    return {"scenario": expected_scenario, "outcome": first["outcome"], "stateSha256": first["stateSha256"]}


def validate_campaign_reports(calibration: dict[str, Any], namespace: dict[str, Any],
                              powercut_reports: Sequence[dict[str, Any]]) -> dict[str, Any]:
    validate_calibration_report(calibration)
    validate_namespace_report(namespace)
    seen: set[str] = set()
    outcomes: dict[str, Any] = {}
    for report in powercut_reports:
        _require(isinstance(report, dict), "power-cut report is not a JSON object")
        scenario = report.get("scenario")
        _require(isinstance(scenario, str) and scenario in POWER_CUT_SCENARIOS,
                 f"unexpected power-cut scenario {scenario!r}")
        _require(scenario not in seen, f"duplicate power-cut scenario {scenario!r}")
        seen.add(scenario)
        outcomes[scenario] = validate_powercut_report(report, scenario)
    missing = set(POWER_CUT_SCENARIOS) - seen
    _require(not missing, "missing required power-cut scenarios: " + ", ".join(sorted(missing)))
    _require(len(powercut_reports) == len(POWER_CUT_SCENARIOS), "unexpected number of power-cut reports")
    return {
        "calibration": "PASS",
        "namespace": "PUBLIC_ORACLE_PASS",
        "powercuts": [outcomes[scenario] for scenario in POWER_CUT_SCENARIOS],
        "claim_boundary": "QEMU Linux guest, ext4, and volatile NBD loss only; not physical host power loss",
    }


def _local_tag(tag: str) -> str:
    return tag.rsplit("}", 1)[-1]


def _testsuites(root: ET.Element) -> Iterable[ET.Element]:
    for element in root.iter():
        if _local_tag(element.tag) == "testsuite":
            yield element


def _count_attribute(suite: ET.Element, name: str, path: Path) -> int:
    value = suite.get(name)
    _require(value is not None and value.isdigit(), f"{path}: test suite has invalid {name} count")
    return int(value)


def validate_selected_test_reports(surefire_dir: Path, failsafe_dir: Path) -> dict[str, Any]:
    totals: dict[str, dict[str, int]] = {}
    for label, directory, required in (
        ("Surefire", surefire_dir, SUREFIRE_TEST_CLASSES),
        ("Failsafe", failsafe_dir, FAILSAFE_IT_CLASSES),
    ):
        _require(directory.is_dir(), f"missing {label} report directory: {directory}")
        reports = sorted(directory.glob("TEST-*.xml"))
        _require(bool(reports), f"{label} produced no JUnit XML reports")
        found: dict[str, dict[str, int]] = {}
        for path in reports:
            try:
                root = ET.parse(path).getroot()
            except (ET.ParseError, OSError) as error:
                raise ValueError(f"cannot parse {label} report {path}: {error}") from error
            for suite in _testsuites(root):
                name = suite.get("name", "").rsplit(".", 1)[-1]
                if name not in required:
                    continue
                _require(name not in found, f"{label} reports selected test class {name} more than once")
                found[name] = {
                    "tests": _count_attribute(suite, "tests", path),
                    "failures": _count_attribute(suite, "failures", path),
                    "errors": _count_attribute(suite, "errors", path),
                    "skipped": _count_attribute(suite, "skipped", path),
                }
                _require(found[name]["tests"] > 0, f"{label} selected test class {name} ran zero tests")
                _require(found[name]["failures"] == 0 and found[name]["errors"] == 0,
                         f"{label} selected test class {name} had failures or errors")
                _require(found[name]["skipped"] == 0, f"{label} selected test class {name} had skipped tests")
        missing = set(required) - set(found)
        _require(not missing, f"{label} did not run selected test classes: " + ", ".join(sorted(missing)))
        totals[label.lower()] = found
    return totals


def _read_json(path: Path, label: str) -> dict[str, Any]:
    _require(path.is_file(), f"missing {label} report: {path}")
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError(f"cannot read {label} report {path}: {error}") from error
    _require(isinstance(value, dict), f"{label} report is not a JSON object")
    return value


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--calibration-report", required=True, type=Path)
    parser.add_argument("--namespace-report", required=True, type=Path)
    parser.add_argument("--powercut-report", required=True, action="append", type=Path,
                        help="one report for each required scenario; repeat exactly three times")
    parser.add_argument("--surefire-dir", required=True, type=Path)
    parser.add_argument("--failsafe-dir", required=True, type=Path)
    parser.add_argument("--summary-json", type=Path)
    parser.add_argument("--github-step-summary", type=Path)
    args = parser.parse_args()
    try:
        campaigns = validate_campaign_reports(
            _read_json(args.calibration_report, "FLUSH/FUA calibration"),
            _read_json(args.namespace_report, "namespace recovery"),
            [_read_json(path, "power-cut") for path in args.powercut_report],
        )
        java_tests = validate_selected_test_reports(args.surefire_dir, args.failsafe_dir)
        summary = {"status": "PASS", "campaigns": campaigns, "java_tests": java_tests}
        payload = json.dumps(summary, indent=2, sort_keys=True) + "\n"
        print(payload, end="")
        if args.summary_json:
            args.summary_json.write_text(payload, encoding="utf-8")
        if args.github_step_summary:
            lines = [
                "## LMDB QEMU durability gate passed",
                "",
                "- Guest model: Linux x86_64 under QEMU KVM with ext4 over volatile NBD.",
                "- Calibration: guest FLUSH/FUA propagation and unsynced overwrite-loss checks passed.",
                "- Namespace-only acknowledged commit: recovery oracle passed.",
                "- Power cuts: " + ", ".join(
                    f"{case['scenario']}={case['outcome']}" for case in campaigns["powercuts"]
                ),
                "- Selected Surefire and Failsafe classes: all reported zero skipped tests.",
                "- Boundary: simulated guest/device power loss only; not physical host power loss.",
            ]
            with args.github_step_summary.open("a", encoding="utf-8") as stream:
                stream.write("\n".join(lines) + "\n")
        return 0
    except (OSError, ValueError) as error:
        print(f"LMDB QEMU CI gate failed: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
